package live.linghe.privateinput;
import android.content.*;import android.util.AtomicFile;import android.security.keystore.*;import javax.crypto.*;import javax.crypto.spec.GCMParameterSpec;import java.io.*;import java.security.KeyStore;import org.json.*;
/** Separate encrypted derived cache/outbox; no legacy sequence, ACK or root key. */
final class ClipboardLiveStore {
 interface Change<T>{T run(JSONObject state)throws Exception;}
 private static final String ALIAS="live.linghe.privateinput.clipboard-live.storage.v1";
 private final Context context;private final File directory;private final AtomicFile file;
 ClipboardLiveStore(Context c){context=c.getApplicationContext();directory=new File(c.getFilesDir(),"ClipboardLive");file=new AtomicFile(new File(directory,"state-v1.enc"));}
 private SecretKey key(boolean create)throws Exception{KeyStore ks=KeyStore.getInstance("AndroidKeyStore");ks.load(null);if(!ks.containsAlias(ALIAS)){if(!create)throw new IOException("剪贴板同步密钥暂不可用");KeyGenerator k=KeyGenerator.getInstance("AES","AndroidKeyStore");k.init(new KeyGenParameterSpec.Builder(ALIAS,KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).setKeySize(256).build());k.generateKey();}return(SecretKey)ks.getKey(ALIAS,null);}
 private JSONObject read()throws Exception{String encoded=AppFiles.readOptional(file,6*1024*1024);if(encoded==null)return empty();JSONObject box=LosslessJson.object(encoded,6*1024*1024);SyncCrypto.require(box.getInt("version")==1);Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,key(false),new GCMParameterSpec(128,SyncCrypto.data(box,"nonce")));cipher.updateAAD(SyncCrypto.bytes("PrivateInput/android-clipboard-live-store/v1\0"));return LosslessJson.object(SyncCrypto.utf8(cipher.doFinal(SyncCrypto.data(box,"ciphertext"))),4*1024*1024);}
 private void write(JSONObject state)throws Exception{byte[] raw=SyncCrypto.bytes(LosslessJson.canonical(state));SyncCrypto.require(raw.length<=4*1024*1024);Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,key(true));cipher.updateAAD(SyncCrypto.bytes("PrivateInput/android-clipboard-live-store/v1\0"));AppFiles.write(file,new JSONObject().put("version",1).put("nonce",SyncCrypto.b64(cipher.getIV())).put("ciphertext",SyncCrypto.b64(cipher.doFinal(raw))).toString(),6*1024*1024);}
 static JSONObject empty()throws Exception{return new JSONObject().put("version",1).put("cursor",0).put("initialized",false).put("outbox",new JSONArray()).put("compatibility",new JSONArray()).put("inbox",new JSONArray()).put("failed",new JSONArray()).put("receipts",new JSONObject());}
 static void retireExpired(JSONObject state,long now)throws Exception{JSONArray out=state.getJSONArray("outbox"),failed=state.optJSONArray("failed");if(failed==null){failed=new JSONArray();state.put("failed",failed);}for(int n=out.length()-1;n>=0;n--)if(out.getJSONObject(n).getJSONObject("wire").getLong("expiresAt")<=now){failed.put(out.getJSONObject(n).put("reason","expired"));out.remove(n);}while(failed.length()>24)failed.remove(0);}
 <T>T change(Change<T> action)throws Exception{return AppFiles.locked(directory,"live.lock",()->{JSONObject state=read();T result=action.run(state);write(state);return result;});}
 JSONObject snapshot()throws Exception{return AppFiles.locked(directory,"live.lock",this::read);}
 boolean authorized(JSONObject credential){try{SharedPreferences p=context.getSharedPreferences("sync-consent",0);return credential!=null&&p.getBoolean(AutoClipboardBridge.ENABLED,false)&&p.getBoolean("clipboard",false)&&p.getLong("generation",0)==credential.getLong("consent")&&p.getLong(AutoClipboardBridge.GENERATION,0)==credential.getLong("automatic")&&credential.getString("privacy").equals(PersonalReset.generation(context))&&!context.getSharedPreferences("privacy-reset",0).getBoolean("pending",false)&&!PersonalReset.expired(context)&&credential.getJSONObject("delegate").getJSONObject("certificate").getLong("expiresAt")>System.currentTimeMillis()/1000;}catch(Exception invalid){return false;}}
 static boolean sameCredential(JSONObject a,JSONObject b){return a!=null&&b!=null&&a.optString("scope").equals(b.optString("scope"))&&a.optString("grant").equals(b.optString("grant"));}
 void clearCredential()throws Exception{change(s->{s.remove("credential");s.put("available",false);return null;});}
 void provision(JSONObject credential)throws Exception{change(s->{JSONObject old=s.optJSONObject("credential");if(!s.optString("binding").equals(credential.getString("scope"))){JSONObject retired=empty();for(String k:new String[]{"cursor","initialized","outbox","compatibility","inbox","failed","receipts"})s.put(k,retired.get(k));}if(old==null||!old.optString("grant").equals(credential.getString("grant")))s.put("available",false);s.put("binding",credential.getString("scope")).put("credential",credential);return null;});}
 JSONArray inbox()throws Exception{JSONObject s=snapshot();if(!authorized(s.optJSONObject("credential")))return new JSONArray();JSONArray result=new JSONArray(),all=s.getJSONArray("inbox");long now=System.currentTimeMillis()/1000;for(int n=0;n<all.length();n++)if(all.getJSONObject(n).getLong("expiresAt")>now)result.put(all.getJSONObject(n));return result;}
 boolean available(){try{JSONObject s=snapshot();return authorized(s.optJSONObject("credential"))&&s.optBoolean("available");}catch(Exception unavailable){return false;}}
 static void resetForDeparture(Context c)throws Exception{ClipboardLiveStore store=new ClipboardLiveStore(c);AppFiles.locked(store.directory,"live.lock",()->{store.file.delete();KeyStore ks=KeyStore.getInstance("AndroidKeyStore");ks.load(null);ks.deleteEntry(ALIAS);return null;});}
}
